// One row per review. Checks that the AI returned every review once and used only allowed themes.
const THEMES = new Set([
  'sizing_fit', 'comfort', 'build_quality', 'durability', 'cleaning_washing', 'dust', 'smell',
  'odor_control', 'clumping', 'ease_of_use', 'app_connectivity', 'noise', 'pet_acceptance',
  'health_effect', 'value_for_money', 'delivery', 'packaging', 'description_accuracy', 'other',
]);
const POLARITY = new Set(['positive', 'negative', 'neutral']);
const clean = s => String(s ?? '').trim().toLowerCase();

// A broken AI answer must not crash the run: that batch's reviews just come out as "missing".
const parse = o => {
  try { return (typeof o === 'string' ? JSON.parse(o) : o) ?? {}; } catch (e) { return {}; }
};
const batches = $('Build Batches').all().map(i => i.json);
const reviews = Object.fromEntries($('Get Reviews').all().map(i => [i.json.review_id, i.json]));

const rows = [];
$input.all().forEach((item, idx) => {
  const batch = batches[idx];
  const answer = parse(item.json.output ?? item.json);
  const tagged = Array.isArray(answer.reviews) ? answer.reviews.filter(Boolean) : [];
  const byId = Object.fromEntries(tagged.map(t => [String(t.review_id).trim().toUpperCase(), t]));

  for (const id of batch.review_ids) {
    const r = reviews[id];
    const t = byId[id];
    const themes = (Array.isArray(t?.themes) ? t.themes.filter(Boolean) : []).map(th => ({
      theme: THEMES.has(clean(th.theme)) ? clean(th.theme) : 'other',
      // An unclear polarity is not counted as a complaint.
      polarity: POLARITY.has(clean(th.polarity)) ? clean(th.polarity) : 'neutral',
      detail: String(th.detail ?? '').replace(/\|/g, '/').trim(),
    }));
    rows.push({
      json: {
        review_id: id,
        sku: r.sku,
        rating: Number(r.rating),
        sentiment: t?.sentiment ?? '',
        themes: themes.map(x => `${x.theme}:${x.polarity}`).join(' | '),
        details: themes.map(x => x.detail).join(' | '),
        quote: t?.quote ?? '',
        tag_status: t ? 'ok' : 'missing',
      },
    });
  }
});
return rows;

// Code does the counting, not the AI: mentions per product × theme, and which ones are real issues.
const MIN_MENTIONS = 4;   // a top issue needs at least 4 reviews...
const MIN_SHARE = 0.10;   // ...and at least 10% of that product's reviews

const products = Object.fromEntries($('Get Products').all().map(i => [i.json.sku, i.json]));
const rows = $input.all().map(i => i.json);

const total = {};
const groups = {};
for (const r of rows) {
  total[r.sku] = (total[r.sku] ?? 0) + 1;
  const themes = r.themes ? r.themes.split(' | ') : [];
  const details = r.details ? r.details.split(' | ') : [];
  themes.forEach((t, i) => {
    const [theme, polarity] = t.split(':');
    const key = `${r.sku}|${theme}|${polarity}`;
    const g = (groups[key] ??= { sku: r.sku, theme, polarity, ids: [], ratings: [], details: [], quotes: [] });
    if (g.ids.includes(r.review_id)) return; // a review counts once per theme
    g.ids.push(r.review_id);
    g.ratings.push(Number(r.rating));
    if (details[i]) g.details.push(details[i]);
    if (r.quote) g.quotes.push(r.quote);
  });
}

const unique = arr => [...new Set(arr.map(s => s.toLowerCase()))];

return Object.values(groups)
  .map(g => {
    const share = g.ids.length / total[g.sku];
    // 'other' is a catch-all of unrelated complaints, so it never counts as one issue.
    const top = g.polarity === 'negative' && g.theme !== 'other' && g.ids.length >= MIN_MENTIONS && share >= MIN_SHARE;
    return {
      sku: g.sku,
      product_name: products[g.sku]?.product_name ?? '',
      theme: g.theme,
      polarity: g.polarity,
      mentions: g.ids.length,
      reviews_total: total[g.sku],
      share_pct: Math.round(share * 100),
      avg_rating: Math.round((g.ratings.reduce((a, b) => a + b, 0) / g.ratings.length) * 10) / 10,
      top_issue: top ? 'yes' : 'no',
      example_details: unique(g.details).slice(0, 4).join(' | '),
      example_quotes: g.quotes.slice(0, 3).map(q => q.replace(/\|/g, '/')).join(' | '),
      review_ids: g.ids.join(' '),
    };
  })
  .sort((a, b) => a.sku.localeCompare(b.sku) || (a.top_issue === 'yes' ? -1 : 0) - (b.top_issue === 'yes' ? -1 : 0) || b.mentions - a.mentions)
  .map(json => ({ json }));

// One item for the AI Advisor: the top issues found by code, plus what customers praise most.
const MAX_HIGHLIGHTS_PER_PRODUCT = 1;
const MIN_PRAISE_MENTIONS = 5;
// Themes that make useful product-page copy (not delivery speed, price or "other").
const COPY_THEMES = new Set([
  'sizing_fit', 'comfort', 'build_quality', 'durability', 'cleaning_washing', 'odor_control', 'clumping',
  'ease_of_use', 'app_connectivity', 'noise', 'pet_acceptance', 'health_effect',
]);

const products = Object.fromEntries($('Get Products').all().map(i => [i.json.sku, i.json]));
const insights = $input.all().map(i => i.json);

const issues = insights
  .filter(r => r.top_issue === 'yes')
  .map((r, i) => ({ ...r, issue_id: `ISSUE ${i + 1}`, page_claims: products[r.sku]?.page_claims ?? '' }));

const highlights = [];
for (const sku of Object.keys(products)) {
  insights
    .filter(r => r.sku === sku && r.polarity === 'positive' && r.mentions >= MIN_PRAISE_MENTIONS && COPY_THEMES.has(r.theme))
    // Don't praise what is also a top issue for the same product.
    .filter(r => !issues.some(i => i.sku === sku && i.theme === r.theme))
    .sort((a, b) => b.mentions - a.mentions)
    .slice(0, MAX_HIGHLIGHTS_PER_PRODUCT)
    .forEach(r => highlights.push(r));
}

const issueLine = r =>
  `${r.issue_id} | ${r.sku} | ${r.product_name} | theme: ${r.theme} | ${r.mentions} of ${r.reviews_total} reviews (${r.share_pct}%), avg rating ${r.avg_rating} | what customers say: ${r.example_details} | quotes: ${r.example_quotes} | product page says: ${r.page_claims}`;
const praiseLine = r =>
  `${r.sku} | ${r.product_name} | theme: ${r.theme} | ${r.mentions} of ${r.reviews_total} reviews | what customers say: ${r.example_details}`;

return [{
  json: {
    issue_count: issues.length,
    issues,
    issues_text: issues.map(issueLine).join('\n') || 'none',
    highlights_text: highlights.map(praiseLine).join('\n') || 'none',
  },
}];

